import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Random;

/** Generates attendance logs of 1, 10 and 50 MB in work/ (not committed - regenerated by run_all.sh). */
public class MakeLogs {
    public static void main(String[] args) throws IOException {
        Path dir = Path.of(args.length > 0 ? args[0] : "work");
        Files.createDirectories(dir);
        String[] status = {"PRESENT", "PRESENT", "PRESENT", "ABSENT", "LATE", "OD"};
        for (int mb : new int[]{1, 10, 50}) {
            Path f = dir.resolve("attendance_" + mb + "MB.log");
            long target = mb * 1024L * 1024L, written = 0;
            Random r = new Random(mb);
            try (BufferedWriter w = Files.newBufferedWriter(f, StandardCharsets.US_ASCII)) {
                long sec = 0;
                while (true) {
                    String line = String.format("2026-11-%02d %02d:%02d:%02d,%d,CSA%02d,%s,Gate-%d%n", 1 + (int) (sec / 86400) % 28,
                            (int) (sec / 3600) % 24, (int) (sec / 60) % 60, (int) sec % 60, 192300000 + r.nextInt(8000), r.nextInt(20),
                            status[r.nextInt(status.length)], 1 + r.nextInt(4));
                    if (written + line.length() > target) break;
                    w.write(line); written += line.length(); sec += 1 + r.nextInt(5);
                }
            }
            System.out.printf("%s  %,d bytes%n", f, Files.size(f));
        }
    }
}
